// Зоны магазина: прямоугольники на карте (x,y,w,h)
const zones={
  veg:{n:"Овощи и фрукты",x:20,y:30,w:100,h:70,side:"L"},
  dairy:{n:"Молочные продукты",x:20,y:120,w:100,h:70,side:"L"},
  bread:{n:"Хлеб и выпечка",x:20,y:210,w:100,h:70,side:"L"},
  meat:{n:"Мясо и рыба",x:180,y:30,w:100,h:70,side:"R"},
  drink:{n:"Напитки",x:180,y:120,w:100,h:70,side:"R"},
  dry:{n:"Бакалея",x:180,y:210,w:100,h:70,side:"R"}
};
const products=[
  {id:1,n:"Яблоки, 1 кг",e:"🍎",p:129,z:"veg",b:"4600001"},
  {id:2,n:"Бананы, 1 кг",e:"🍌",p:99,z:"veg",b:"4600002"},
  {id:3,n:"Молоко 3,2%, 1 л",e:"🥛",p:89,z:"dairy",b:"4600003"},
  {id:4,n:"Сыр «Российский»",e:"🧀",p:349,z:"dairy",b:"4600004"},
  {id:5,n:"Яйца, 10 шт.",e:"🥚",p:119,z:"dairy",b:"4600005"},
  {id:6,n:"Батон нарезной",e:"🍞",p:49,z:"bread",b:"4600006"},
  {id:7,n:"Круассан",e:"🥐",p:59,z:"bread",b:"4600007"},
  {id:8,n:"Куриное филе, 1 кг",e:"🍗",p:379,z:"meat",b:"4600008"},
  {id:9,n:"Лосось, 300 г",e:"🐟",p:459,z:"meat",b:"4600009"},
  {id:10,n:"Апельсиновый сок",e:"🧃",p:139,z:"drink",b:"4600010"},
  {id:11,n:"Вода, 1,5 л",e:"💧",p:45,z:"drink",b:"4600011"},
  {id:12,n:"Макароны, 400 г",e:"🍝",p:79,z:"dry",b:"4600012"},
  {id:13,n:"Рис, 900 г",e:"🍚",p:109,z:"dry",b:"4600013"},
  {id:14,n:"Кофе молотый",e:"☕",p:329,z:"dry",b:"4600014"},
  {id:15,n:"Клубника, 500 г",e:"🍓",p:249,z:"veg",b:"4600015"},
  {id:16,n:"Апельсины, 1 кг",e:"🍊",p:139,z:"veg",b:"4600016"},
  {id:17,n:"Груши зелёные, 1 кг",e:"🍐",p:159,z:"veg",b:"4600017"},
  {id:18,n:"Голубика, 125 г",e:"🫐",p:289,z:"veg",b:"4600018"},
  {id:19,n:"Личи, 500 г",e:"🍒",p:349,z:"veg",b:"4600019"},
  {id:20,n:"Персики, 1 кг",e:"🍑",p:199,z:"veg",b:"4600020"},
  {id:21,n:"Ананас",e:"🍍",p:229,z:"veg",b:"4600021"},
  {id:22,n:"Груши жёлтые, 1 кг",e:"🍐",p:169,z:"veg",b:"4600022"},
  {id:23,n:"Говядина, 1 кг",e:"🥩",p:599,z:"meat",b:"4600023"},
  {id:24,n:"Мраморная говядина Вагю, 300 г",e:"🥩",p:2990,z:"meat",b:"4600024"},
  {id:25,n:"Иберико, 300 г",e:"🥩",p:1190,z:"meat",b:"4600025"},
  {id:26,n:"Верблюжатина, 1 кг",e:"🥩",p:899,z:"meat",b:"4600026"},
  {id:27,n:"Мясо яка, 1 кг",e:"🥩",p:949,z:"meat",b:"4600027"},
  {id:28,n:"Кенгуру, 500 г",e:"🥩",p:1390,z:"meat",b:"4600028"},
  {id:29,n:"Страус, 1 кг",e:"🥩",p:1190,z:"meat",b:"4600029"},
  {id:30,n:"Лобстер, 1 шт.",e:"🦞",p:2490,z:"meat",b:"4600030"}
];
const IMGS={1:"data:image/webp;base64,",15:"data:image/webp;base64,",16:"data:image/webp;base64,",17:"data:image/webp;base64,",18:"data:image/webp;base64,",19:"data:image/webp;base64,",20:"data:image/webp;base64,",21:"data:image/webp;base64,",22:"data:image/webp;base64,",23:"data:image/webp;base64,",24:"data:image/webp;base64,",25:"data:image/webp;base64,",26:"data:image/webp;base64,",27:"data:image/webp;base64,",28:"data:image/webp;base64,",29:"data:image/webp;base64,",30:"data:image/webp;base64,"};
const pic=p=>IMGS[p.id]?`<img src="${IMGS[p.id]}" alt="${p.n}">`:p.e;
const $=s=>document.querySelector(s);
const rub=n=>n.toLocaleString("ru-RU")+" ₽";
// цена товара в выбранном магазине: где-то ниже, где-то выше
function price(p){
  const s=curStore;
  const k=((p.id*7+s.id*3)%9-4)*0.02;
  return Math.round(p.p*(s.f+k)*(s.hi.includes(p.id)?1.7:1));
}
const has=p=>!curStore.no.includes(p.id);
const pricey=p=>curStore.hi.includes(p.id);
let cart={},target=null;

// Магазины
let curStore=stores[0];

// Каталог + поиск
function renderCatalog(){
  const q=$("#q").value.trim().toLowerCase();
  const list=products.filter(p=>p.n.toLowerCase().includes(q)&&(!curCat||curCat==="all"||p.z===curCat)&&has(p));
  $("#grid").innerHTML=list.length?list.map(p=>`
    <div class="card">
      <div class="emoji">${pic(p)}</div>
      <div class="name">${p.n}</div>
      <div class="zone">${zones[p.z].n}</div>
      <div class="price">${rub(price(p))}${pricey(p)?' <span class="warn">дорого</span>':''}</div>
      <div class="row">
        <button onclick="add(${p.id})">В корзину</button>
        <button class="sec" onclick="showPath(${p.id})">Путь</button>
      </div>
    </div>`).join(""):'<div class="hint">Ничего не найдено</div>';
}
$("#q").addEventListener("input",()=>view());

// Навигатор
function drawMap(){
  let s=`<rect x="5" y="5" width="290" height="350" rx="10" fill="none" stroke="var(--line)" stroke-width="2"/>`;
  for(const k in zones){
    const z=zones[k],hit=target&&products.find(p=>p.id===target).z===k;
    s+=`<rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" rx="8" fill="${hit?"var(--accent2)":"var(--card)"}" stroke="${hit?"var(--accent)":"var(--line)"}" stroke-width="${hit?3:1.5}"/>
    <text x="${z.x+z.w/2}" y="${z.y+z.h/2+4}" text-anchor="middle" font-size="11" fill="var(--text)">${z.n}</text>`;
  }
  s+=`<text x="150" y="352" text-anchor="middle" font-size="11" fill="var(--muted)">Вход</text>`;
  s+=`<circle cx="150" cy="335" r="6" fill="var(--accent)"/>`;
  if(target){
    const z=zones[products.find(p=>p.id===target).z];
    const cy=z.y+z.h/2,tx=z.side==="L"?z.x+z.w:z.x;
    s+=`<polyline points="150,335 150,${cy} ${tx},${cy}" fill="none" stroke="var(--path)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="8 6"/>
    <circle cx="${tx}" cy="${cy}" r="7" fill="var(--path)"/>`;
  }
  $("#svg").innerHTML=s;
}
function showPath(id){
  target=id;const p=products.find(x=>x.id===id);
  $("#mapHint").textContent=`${p.e} ${p.n} — ${zones[p.z].n}`;
  drawMap();tab("map");
}

// Сканер штрихкодов (демо)
function scan(code){
  const p0=products.find(x=>x.b===code.trim());const p=p0&&has(p0)?p0:null;
  $("#scanRes").innerHTML=p?`<div class="card"><div class="emoji">${pic(p)}</div>
    <div class="name">${p.n}</div><div class="zone">Штрихкод ${p.b} · ${zones[p.z].n}</div>
    <div class="price">${rub(price(p))}</div>
    <div class="row"><button onclick="add(${p.id})">В корзину</button><button class="sec" onclick="showPath(${p.id})">Путь</button></div></div>`
    :`<div class="hint">${p0?p0.n+" — нет в наличии в магазине «"+curStore.name+"».":"Товар с таким кодом не найден."}</div>`;
}
$("#scanBtn").onclick=()=>scan($("#code").value);
$("#rndBtn").onclick=()=>{const av=products.filter(has),p=av[Math.floor(Math.random()*av.length)];$("#code").value=p.b;scan(p.b)};

// Корзина
function add(id){cart[id]=(cart[id]||0)+1;renderCart()}
function chg(id,d){cart[id]=(cart[id]||0)+d;if(cart[id]<=0)delete cart[id];renderCart()}
function renderCart(){
  const ids=Object.keys(cart);let sum=0,n=0;
  $("#cart").innerHTML=ids.length?ids.map(i=>{
    const p=products.find(x=>x.id==i),q=cart[i];sum+=price(p)*q;n+=q;
    return `<div class="card item"><div class="emoji">${pic(p)}</div>
      <div class="grow"><div class="name">${p.n}</div><div class="zone">${rub(price(p))} × ${q}</div></div>
      <div class="qty row"><button class="sec" onclick="chg(${p.id},-1)">−</button><button class="sec" onclick="chg(${p.id},1)">+</button></div></div>`}).join("")
    :'<div class="hint">Список покупок пуст. Добавьте товары из каталога.</div>';
  $("#total").textContent=ids.length?"Итого: "+rub(sum):"";
  $("#cnt").textContent=n?`Корзина (${n})`:"Корзина";
}

// Вкладки
function tab(t){
  ["catalog","map","scan","cart"].forEach(x=>$("#tab-"+x).classList.toggle("hide",x!==t));
  document.querySelectorAll("nav button").forEach(b=>b.classList.toggle("on",b.dataset.t===t));
}
$("#nav").addEventListener("click",e=>{const b=e.target.closest("button");if(b)tab(b.dataset.t)});

function selectStore(id){
  curStore=stores.find(s=>s.id===id)||stores[0];
  $("#curStore").innerHTML=`<img class="logo mini" src="${LOGOS[curStore.id]}" alt=""> ${curStore.name} · ${curStore.addr}`;
  curCat=null;$("#q").value="";Object.keys(cart).forEach(i=>{if(!has(products.find(x=>x.id==i)))delete cart[i]});renderCats();view();renderCart();$("#scanRes").innerHTML="";
}

// Стартовое меню выбора магазина
const LOGOS={1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,",4:"data:image/webp;base64,",5:"data:image/webp;base64,"};
const icons={1:"🏪",2:"🏬",3:"🏢",4:"🛒",5:"🧺"};
const lvl=f=>f<1?"цены ниже среднего":f>1?"цены выше среднего":"средние цены";
$("#welcomeList").innerHTML=stores.map(s=>`<button class="store" data-id="${s.id}"><img class="logo" src="${LOGOS[s.id]}" alt="${s.name}"><span class="grow"><b>${s.name}</b><small>${s.addr}</small><small class="lv ${s.f<1?'low':s.f>1?'high':''}">${lvl(s.f)}</small></span><span>›</span></button>`).join("");
$("#stat").textContent=stores.length+" магазинов · "+products.length+" товаров";
$("#welcomeList").addEventListener("click",e=>{
  const b=e.target.closest(".store");if(!b)return;
  selectStore(+b.dataset.id);
  document.body.classList.remove("start");tab("catalog");window.scrollTo(0,0);
});
$("#back").onclick=()=>{document.body.classList.add("start");window.scrollTo(0,0)};

document.querySelectorAll(".aboutBtn").forEach(b=>b.addEventListener("click",()=>{$("#about").classList.remove("hide");$("#about").scrollTop=0}));
$("#aboutClose").onclick=()=>$("#about").classList.add("hide");
// Переключение темы
let dark=false;
document.querySelectorAll(".themeBtn").forEach(b=>b.onclick=()=>{
  dark=!dark;document.documentElement.dataset.theme=dark?"dark":"light";
  document.querySelectorAll(".themeBtn").forEach(x=>x.textContent=dark?"☀️":"🌙");
});

// Анимация волны при нажатии на любую кнопку
document.addEventListener("click",e=>{
  const b=e.target.closest("button");if(!b)return;
  const r=b.getBoundingClientRect(),d=Math.max(r.width,r.height),s=document.createElement("span");
  s.className="rip";s.style.cssText=`width:${d}px;height:${d}px;left:${e.clientX-r.left-d/2}px;top:${e.clientY-r.top-d/2}px`;
  b.appendChild(s);setTimeout(()=>s.remove(),600);
  const c=$("#cnt");c.classList.remove("bump");void c.offsetWidth;c.classList.add("bump");
});
// Выбор категории после выбора магазина
let curCat=null;
const cats=[{k:"veg",i:"🥬"},{k:"dairy",i:"🥛"},{k:"bread",i:"🍞"},{k:"meat",i:"🍗"},{k:"drink",i:"🧃"},{k:"dry",i:"🍝"}];
const renderCats=()=>$("#cats").innerHTML=cats.map(c=>`<button class="tile" data-k="${c.k}"><span class="si">${c.i}</span><span>${zones[c.k].n}</span><small>${products.filter(p=>p.z===c.k&&has(p)).length} тов.</small></button>`).join("")+`<button class="tile all" data-k="all"><span class="si">🛍️</span><span>Все товары</span></button>`;
function view(){
  const inCat=curCat!==null||$("#q").value.trim()!=="";
  $("#cats").classList.toggle("hide",inCat);
  $("#prods").classList.toggle("hide",!inCat);
  $("#catTitle").textContent=curCat?(curCat==="all"?"Все товары":zones[curCat].n):"Результаты поиска";
  renderCatalog();
}
$("#cats").addEventListener("click",e=>{const b=e.target.closest(".tile");if(!b)return;curCat=b.dataset.k;view();window.scrollTo(0,0)});
$("#catBack").onclick=()=>{curCat=null;$("#q").value="";view()};
renderCats();view();drawMap();renderCart();
